const r = $input.first().json;
if (!r.files || r.files.length === 0) {
  return [{ json: { ok: false, month: r.month, message: r.message || 'データなし' } }];
}
const out = [];
for (const f of r.files) {
  if (!f.base64) { out.push({ json: { zip: f.zip, error: f.error || 'no data' } }); continue; }
  const buf = Buffer.from(f.base64, 'base64');
  // giftcard のCSVは Shift-JIS(MS932)。先頭行のみUTF-8化してプレビュー表示（全文は必要時に）
  let header = '';
  try { header = new TextDecoder('shift_jis').decode(buf).split(/\r?\n/)[0].slice(0, 200); } catch (e) { header = '(decode err: ' + e.message + ')'; }
  const item = { json: { month: r.month, zip: f.zip, filename: f.filename, bytes: f.bytes, header }, binary: {} };
  // 元CSV(Shift-JIS)をそのままバイナリ化 → SharePoint等へアップロード可能
  item.binary.csv = await this.helpers.prepareBinaryData(buf, f.filename, 'text/csv');
  out.push(item);
}
return out;
